     1→/**
     2→ * Setup status utilities
     3→ *
     4→ * Extracted from cli/commands/setup.ts to avoid CLI module dependency for doctor.ts.
     5→ * Provides setup status information without output formatting.
     6→ *
     7→ * AC: @doctor-command ac-setup-agent-hooks, ac-setup-skills-agents-md, ac-partial-init, ac-staleness-unknown
     8→ */
     9→
    10→import * as fs from "node:fs/promises";
    11→import * as path from "node:path";
    12→import {
    13→  detectAgentFromEnv,
    14→  type AgentType,
    15→  type AgentConfidence,
    16→} from "./agent-detection.js";
    17→
    18→/**
    19→ * Detected agent type
    20→ */
    21→export type { AgentType } from "./agent-detection.js";
    22→
    23→/**
    24→ * Setup status information
    25→ * AC: @enhanced-setup ac-7, ac-8 - status reporting
    26→ */
    27→export interface SetupStatus {
    28→  agent: {
    29→    detected: AgentType;
    30→    confidence: AgentConfidence;
    31→  };
    32→  hooks: {
    33→    promptCheck: boolean;
    34→    stop: boolean;
    35→    preToolUse: boolean;
    36→    guardsPresent: string[];
    37→  };
    38→  skills: {
    39→    total: number;
    40→    rendered: number;
    41→    drifted: number;
    42→  };
    43→  plugin: {
    44→    marketplaceRegistered: boolean;
    45→    marketplaceHealthy: boolean;
    46→    pluginEnabled: boolean;
    47→    registeredPath?: string;
    48→    healthMessage?: string;
    49→  };
    50→  agentsMd: {
    51→    exists: boolean;
    52→    status: "current" | "stale" | "missing" | "unknown";
    53→    generatedAt?: string;
    54→  };
    55→  seeding: {
    56→    permissionsSeeded: boolean;
    57→    memorySeeded: boolean;
    58→    memoryPath?: string;
    59→  };
    60→  /** Error message if status check failed */
    61→  error?: string;
    62→}
    63→
    64→/**
    65→ * Guard scripts that can be installed
    66→ */
    67→const GUARD_SCRIPTS: Record<string, boolean> = {
    68→  "bash-guard.mjs": true,
    69→  "write-guard.mjs": true,
    70→  "edit-guard.mjs": true,
    71→};
    72→
    73→/**
    74→ * Detect the agent type in use.
    75→ */
    76→export async function detectAgent(): Promise<{
    77→  type: AgentType;
    78→  confidence: AgentConfidence;
    79→}> {
    80→  const detected = detectAgentFromEnv();
    81→  if (detected.type !== "unknown") {
    82→    return { type: detected.type, confidence: detected.confidence };
    83→  }
    84→
    85→  // Check for Claude Code by looking for .claude directory
    86→  // This is a medium confidence indicator
    87→  if (process.env.HOME) {
    88→    // Global Claude Code config at ~/.claude
    89→    const globalClaudeDir = path.join(process.env.HOME, ".claude");
    90→    try {
    91→      const stats = await fs.stat(globalClaudeDir);
    92→      if (stats.isDirectory()) {
    93→        return { type: "claude-code", confidence: "medium" };
    94→      }
    95→    } catch {
    96→      // Directory doesn't exist
    97→    }
    98→  }
    99→
   100→  return { type: "unknown", confidence: "low" };
   101→}
   102→
   103→/**
   104→ * Debug logging helper
   105→ */
   106→function debugLog(message: string, _error?: unknown): void {
   107→  if (process.env.KSPEC_DEBUG === "1") {
   108→    console.error(`[DEBUG] ${message}`);
   109→  }
   110→}
   111→
   112→/**
   113→ * Get the current setup status for a project.
   114→ *
   115→ * AC: @doctor-command ac-setup-agent-hooks — checks hooks status
   116→ * AC: @doctor-command ac-setup-skills-agents-md — checks skills and agents.md
   117→ * AC: @doctor-command ac-partial-init — handles missing setup artifacts
   118→ * AC: @doctor-command ac-staleness-unknown — returns "unknown" when staleness cannot be determined
   119→ *
   120→ * @param projectDir Project root directory
   121→ */
   122→export async function getSetupStatus(projectDir: string): Promise<SetupStatus> {
   123→  const detected = await detectAgent();
   124→  const configPath = path.join(projectDir, ".claude", "settings.json");
   125→  const hooksDir = path.join(projectDir, ".claude", "hooks");
   126→  const agentsMdPath = path.join(projectDir, "kspec-agents.md");
   127→  const hashPath = path.join(projectDir, ".kspec", ".kspec-agents-hash");
   128→  const skillsDir = path.join(projectDir, ".claude", "skills");
   129→
   130→  // Check hooks
   131→  const hooks = {
   132→    promptCheck: false,
   133→    stop: false,
   134→    preToolUse: false,
   135→    guardsPresent: [] as string[],
   136→  };
   137→
   138→  try {
   139→    const configContent = await fs.readFile(configPath, "utf-8");
   140→    const config = JSON.parse(configContent);
   141→    const hooksConfig = config.hooks || {};
   142→
   143→    // Check UserPromptSubmit
   144→    const promptHooks = hooksConfig.UserPromptSubmit as
   145→      | Array<{ hooks?: Array<{ command?: string }> }>
   146→      | undefined;
   147→    hooks.promptCheck =
   148→      promptHooks?.some((entry) =>
   149→        entry.hooks?.some((h) => h.command?.includes("prompt-check"))
   150→      ) ?? false;
   151→
   152→    // Check Stop
   153→    const stopHooks = hooksConfig.Stop as
   154→      | Array<{ hooks?: Array<{ command?: string }> }>
   155→      | undefined;
   156→    hooks.stop =
   157→      stopHooks?.some((entry) =>
   158→        entry.hooks?.some((h) => h.command?.includes("checkpoint"))
   159→      ) ?? false;
   160→
   161→    // Check PreToolUse
   162→    const preToolUseHooks = hooksConfig.PreToolUse as
   163→      | Array<{ hooks?: Array<{ command?: string }> }>
   164→      | undefined;
   165→    hooks.preToolUse =
   166→      preToolUseHooks?.some((entry) =>
   167→        entry.hooks?.some((h) => h.command?.includes(".claude/hooks/"))
   168→      ) ?? false;
   169→  } catch (err) {
   170→    debugLog("Failed to read hooks config for status", err);
   171→  }
   172→
   173→  // Check guard scripts
   174→  try {
   175→    const guardFiles = await fs.readdir(hooksDir);
   176→    for (const name of Object.keys(GUARD_SCRIPTS)) {
   177→      if (guardFiles.includes(name)) {
   178→        hooks.guardsPresent.push(name);
   179→      }
   180→    }
   181→  } catch (err) {
   182→    debugLog("Hooks dir doesn't exist", err);
   183→  }
   184→
   185→  // Check skills
   186→  const skills = {
   187→    total: 0,
   188→    rendered: 0,
   189→    drifted: 0,
   190→  };
   191→
   192→  // Helper to check a single skill directory for kspec-managed SKILL.md
   193→  async function checkSingleSkillDir(dirPath: string, dirName: string): Promise<void> {
   194→    const skillMdPath = path.join(dirPath, "SKILL.md");
   195→    try {
   196→      const content = await fs.readFile(skillMdPath, "utf-8");
   197→      if (content.includes("<!-- kspec-managed -->")) {
   198→        skills.total++;
   199→        skills.rendered++;
   200→      }
   201→    } catch (err) {
   202→      debugLog(`SKILL.md doesn't exist in ${dirName}`, err);
   203→    }
   204→  }
   205→
   206→  // Helper to scan a directory for skill subdirectories
   207→  async function scanForSkills(baseDir: string, label: string): Promise<void> {
   208→    try {
   209→      const dirs = await fs.readdir(baseDir, { withFileTypes: true });
   210→      for (const dir of dirs) {
   211→        if (dir.isDirectory()) {
   212→          await checkSingleSkillDir(path.join(baseDir, dir.name), `${label}/${dir.name}`);
   213→        }
   214→      }
   215→    } catch (err) {
   216→      debugLog(`${label} dir doesn't exist`, err);
   217→    }
   218→  }
   219→
   220→  // Scan .claude/skills/ (project/local skills)
   221→  await scanForSkills(skillsDir, "skills");
   222→
   223→  // Check plugin marketplace health
   224→  // AC: @enhanced-setup ac-7, ac-8
   225→  const plugin = {
   226→    marketplaceRegistered: false,
   227→    marketplaceHealthy: false,
   228→    pluginEnabled: false,
   229→    registeredPath: undefined as string | undefined,
   230→    healthMessage: undefined as string | undefined,
   231→  };
   232→
   233→  try {
   234→    const { checkMarketplaceHealth } = await import(
   235→      "../lib/claude-plugin-registry.js"
   236→    );
   237→    const health = await checkMarketplaceHealth();
   238→    plugin.marketplaceRegistered = health.status !== "missing";
   239→    plugin.marketplaceHealthy = health.status === "healthy";
   240→    plugin.registeredPath = health.registeredPath;
   241→    plugin.healthMessage = health.message;
   242→  } catch (err) {
   243→    debugLog("Could not check marketplace health", err);
   244→    plugin.healthMessage = "Health check unavailable";
   245→  }
   246→
   247→  // Check if plugin is enabled in project settings
   248→  try {
   249→    const configContent = await fs.readFile(configPath, "utf-8");
   250→    const config = JSON.parse(configContent);
   251→    plugin.pluginEnabled = config.enabledPlugins?.["kspec@kspec-plugins"] === true;
   252→  } catch (err) {
   253→    debugLog("Could not check plugin enablement", err);
   254→  }
   255→
   256→  // Check agents.md
   257→  const agentsMd: SetupStatus["agentsMd"] = {
   258→    exists: false,
   259→    status: "missing",
   260→  };
   261→
   262→  try {
   263→    await fs.access(agentsMdPath);
   264→    agentsMd.exists = true;
   265→
   266→    try {
   267→      const hashContent = await fs.readFile(hashPath, "utf-8");
   268→      const hashData = JSON.parse(hashContent);
   269→      agentsMd.generatedAt = hashData.generatedAt;
   270→
   271→      // AC: @doctor-command ac-staleness-unknown
   272→      // Compare stored hash against current meta to detect staleness
   273→      try {
   274→        const { initContext, loadMetaContext } = await import("./index.js");
   275→        // Dynamic import agents.js from CLI commands
   276→        const { computeMetaHash, loadTemplateSections, getPackageRoot } = await import(
   277→          "../cli/commands/agents.js"
   278→        );
   279→        const ctx = await initContext();
   280→        if (ctx.manifestPath) {
   281→          const metaCtx = await loadMetaContext(ctx);
   282→          let templateSections: string[] = [];
   283→          try {
   284→            templateSections = await loadTemplateSections(getPackageRoot());
   285→          } catch (err) {
   286→            debugLog("Templates not available for staleness check", err);
   287→          }
   288→          const currentHash = computeMetaHash(
   289→            metaCtx.skills,
   290→            metaCtx.conventions,
   291→            metaCtx.workflows,
   292→            templateSections
   293→          );
   294→          agentsMd.status = hashData.metaHash === currentHash ? "current" : "stale";
   295→        } else {
   296→          // AC: @doctor-command ac-staleness-unknown — no manifest means we can't check
   297→          agentsMd.status = "unknown";
   298→        }
   299→      } catch (err) {
   300→        // AC: @doctor-command ac-staleness-unknown — hash computation failed
   301→        debugLog("Could not compute meta hash for staleness check", err);
   302→        agentsMd.status = "unknown";
   303→      }
   304→    } catch (err) {
   305→      debugLog("Hash file missing or invalid, marking stale", err);
   306→      agentsMd.status = "stale";
   307→    }
   308→  } catch (err) {
   309→    debugLog("kspec-agents.md doesn't exist", err);
   310→  }
   311→
   312→  // Check seeding state
   313→  const seeding: SetupStatus["seeding"] = {
   314→    permissionsSeeded: false,
   315→    memorySeeded: false,
   316→  };
   317→
   318→  try {
   319→    const configContent = await fs.readFile(
   320→      path.join(projectDir, ".claude", "settings.json"),
   321→      "utf-8"
   322→    );
   323→    const config = JSON.parse(configContent);
   324→    seeding.permissionsSeeded = !!config.permissions;
   325→  } catch (err) {
   326→    debugLog("Could not check permissions seeding state", err);
   327→  }
   328→
   329→  if (detected.type === "claude-code") {
   330→    try {
   331→      const { claudeCodeMemoryWriter } = await import(
   332→        "../cli/commands/setup-seeding.js"
   333→      );
   334→      const memoryExists = await claudeCodeMemoryWriter.exists(projectDir);
   335→      seeding.memorySeeded = memoryExists;
   336→      if (memoryExists) {
   337→        seeding.memoryPath = claudeCodeMemoryWriter.getMemoryPath(projectDir);
   338→      }
   339→    } catch (err) {
   340→      debugLog("Could not check memory seeding state", err);
   341→    }
   342→  }
   343→
   344→  return {
   345→    agent: {
   346→      detected: detected.type,
   347→      confidence: detected.confidence,
   348→    },
   349→    hooks,
   350→    skills,
   351→    plugin,
   352→    agentsMd,
   353→    seeding,
   354→  };
   355→}
   356→
